#!/usr/bin/env bash
# step53 — Reseller-bot order notifications (#1), website side. Fires order events
# (new/paid/delivered/review/rejected) to the bot's /api/notify. Fire-and-forget:
# never blocks or breaks an order, silent until the bot endpoint is live.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step53-$TS
mkdir -p "$BAK/lib" "$BAK/routes"
cp "$APP/lib/botapi.js" "$BAK/lib/botapi.js"
cp "$APP/routes/checkout.js" "$BAK/routes/checkout.js"
restore(){ echo "!! rollback"; cp "$BAK/lib/botapi.js" "$APP/lib/botapi.js"; cp "$BAK/routes/checkout.js" "$APP/routes/checkout.js"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR
writef(){ local dest="$APP/$1" b64="$2" md5="$3"; base64 -d "$b64" > "$dest"; local got; got=$(md5sum "$dest"|awk '{print $1}'); echo "   $1 $got $([ "$got" = "$md5" ] && echo OK || echo MISMATCH)"; [ "$got" = "$md5" ] || { echo "!! md5 mismatch $1"; false; }; }
cat > /tmp/s53_botapi.b64 <<'B53_botapi'

B53_botapi
writef "lib/botapi.js" /tmp/s53_botapi.b64 "36b054e32d6e222d1f2f94096b16b26d"
rm -f /tmp/s53_botapi.b64
cat > /tmp/s53_checkout.b64 <<'B53_checkout'

B53_checkout
writef "routes/checkout.js" /tmp/s53_checkout.b64 "34c684152378efddb6e01cc839edb5ab"
rm -f /tmp/s53_checkout.b64

echo "==> node --check"
node --check "$APP/lib/botapi.js"
node --check "$APP/routes/checkout.js"
echo "==> verify notify wired"
grep -q 'function notify(' "$APP/lib/botapi.js" || { echo "!! botapi.notify missing"; false; }
grep -q 'notifyOrder(' "$APP/routes/checkout.js" || { echo "!! notifyOrder missing"; false; }

echo "==> pm2 restart gsz"; pm2 restart gsz --update-env >/dev/null; sleep 3
H=$(curl -s -m 15 http://127.0.0.1:3900/ || true)
grep -q '</html>' <<<"$H" || { echo "!! home broken"; false; }
SLUG=$(grep -oE '/product/[a-z0-9-]+' <<<"$H" | head -1 | sed 's#/product/##')
[ -n "$SLUG" ] || { echo "!! no slug"; false; }
PP=$(curl -s -m 15 "http://127.0.0.1:3900/product/$SLUG" || true)
grep -q '</html>' <<<"$PP" || { echo "!! product page broken"; false; }
CO=$(curl -s -m 15 "http://127.0.0.1:3900/checkout?p=$SLUG&plan=0&region=PK" || true)
grep -q 'Place order' <<<"$CO" || { echo "!! single checkout broken"; false; }
CC=$(curl -s -m 15 -X POST http://127.0.0.1:3900/cart/checkout --data-urlencode "cart=[{\"slug\":\"$SLUG\",\"planIdx\":0,\"qty\":1}]" --data-urlencode "region=PK" || true)
grep -q 'Place order' <<<"$CC" || { echo "!! combined checkout broken"; false; }

trap - ERR
echo "==> step53 OK — order notifications wired (website side). Backup: $BAK"
